    host.append(u.row(u.field('Start from a validated blueprint',choose),u.button('Use this validated blueprint',async()=>{const result=await act('design-select',{designId:design.id});if(result)await next();},{primary:true})),u.el('p',`Quality ${(Number(design.qualityPpm??1000000)/1e6).toFixed(3)} · model cost ${design.cost??'—'}`,'lab-op-hint'));
    const form=u.el('div',undefined,'lab-op-toolbar'),name=u.input(preferences.designName??'My biological design',{onChange:v=>preferences.designName=v});name.maxLength=48;const challenge=u.select([[1000000,'1.0×'],[1500000,'1.5×'],[2000000,'2.0×']],preferences.challenge??design.challenge??2000000,v=>{preferences.challenge=Number(v);draftEpoch++;designReport=null;if(designer)designer.setGraph(designer.getGraph());summary.textContent='Requested challenge changed. Run a new experiment.';});
    const save=u.button('Validate & save my blueprint',async()=>{const graph=designer?.getGraph()??draftGraph;await act('design-save',{name:name.value.trim(),graph,challenge:Number(challenge.value)});},{primary:true});form.append(u.field('Requested challenge',challenge),save);host.append(form);
    const summary=u.el('p',designReport?`Last test: ${designReport}`:'Edit connections below, then validate and save.','lab-op-hint');host.append(summary);
    const mount=u.el('div',undefined,'lab-op-designer');host.append(mount);
    const rename=u.el('details');rename.open=false;rename.append(u.el('summary','Rename your design'),u.field('Your design name',name));host.append(rename);
    const rules=u.el('details');rules.open=false;rules.append(u.el('summary','Model rules & verification'),u.note('A line is an actual functional allocation between permitted ports. Drawing more lines does not create capacity or a passing design. The fixed model supports 15 functional cells, six organ containers and one organism.'),u.note('Saving runs the complete 73-round experiment. Invalid blueprints are not saved. Unsaved edits do not change manufactured specimens.'));host.append(rules);
    designSurface=mount;designControls=[choose,name,challenge,save,...host.querySelectorAll?.('button')??[]];const start=structuredClone(draftGraph);designer=mountLabDesigner(mount,{document,graph:start,onChange:graph=>{draftGraph=graph;draftEpoch++;designReport=null;summary.textContent='Draft changed. The previous experiment no longer applies.';},onValidate:async graph=>{const epoch=draftEpoch,response=await act('design-test',{graph,challenge:Number(challenge.value)});if(!response)throw Error('MODEL_TEST');if(epoch!==draftEpoch)return{status:'STALE'};const report=response.state.lastResult;if(report.action!=='design-test'||report.rounds!==73)throw Error('MODEL_TEST');designReport=`PASS / ${report.rounds} rounds / quality ${Number(report.qualityPpm)/1e6} / cost ${report.cost}`;summary.textContent=designReport;return{...report,status:'PASS'};}});applyDesignLock();
